package shop;

import java.math.BigDecimal;
import java.math.RoundingMode;

public class DiscountService {
    /** Returns the order total for a given subtotal. */
    public BigDecimal total(BigDecimal subtotal) {
        return subtotal;
    }

    public BigDecimal checkedTotal(BigDecimal subtotal) {
        if (subtotal == null || subtotal.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("subtotal must not be null or negative");
        }
        BigDecimal result = subtotal;
        if (subtotal.compareTo(new BigDecimal("100")) > 0) {
            result = subtotal.multiply(new BigDecimal("0.9"));
        }
        return result.setScale(2, RoundingMode.HALF_UP);
    }
}

